+    /**
+     * Flush local log segments for all offsets up to offset-1
+     *
+     * @param offset The offset to flush up to (non-inclusive); the new recovery point
+     */
+    public void flushUptoOffsetExclusive(long offset) {
+        flush(offset, false);
+    }
