+            logOffsetsListener = LogOffsetsListener.NO_OP_OFFSETS_LISTENER;
+            maybeFlushMetadataFile();
+            localLog.checkIfMemoryMappedBufferClosed();
+            producerExpireCheck.cancel(true);
